    // Firebase REST API
    const FIREBASE_URL = "https://pim-tarot-default-rtdb.asia-southeast1.firebasedatabase.app";
    
    // Spread types for counter
    const spreadTypes = [1, 2, 3, 4, 10, 12];
    
    async function loadCounter() {
      try {
        const response = await fetch(FIREBASE_URL + "/counter/readings.json");
        const count = await response.json();
        updateCounterDisplay(count || 0);
      } catch (error) {
        console.error("Error loading counter:", error);
        updateCounterDisplay(0);
      }
    }
    
    async function loadSpreadCounters() {
      for (const type of spreadTypes) {
        try {
          const response = await fetch(FIREBASE_URL + "/counter/spread_" + type + ".json");
          const count = await response.json();
          updateSpreadCounterDisplay(type, count || 0);
        } catch (error) {
          console.error("Error loading spread counter:", error);
          updateSpreadCounterDisplay(type, 0);
        }
      }
    }
    
    function updateSpreadCounterDisplay(type, count) {
      const el = document.getElementById('plays-' + type);
      if (el) {
        el.textContent = 'เปิดไปแล้ว ' + count.toLocaleString() + ' ครั้ง';
      }
    }
    
    async function incrementReadingCount() {
      try {
        // Increment total counter
        const getResponse = await fetch(FIREBASE_URL + "/counter/readings.json");
        const currentCount = await getResponse.json() || 0;
        const newCount = currentCount + 1;
        
        await fetch(FIREBASE_URL + "/counter/readings.json", {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(newCount)
        });
        
        updateCounterDisplay(newCount);
        
        // Increment spread-specific counter
        const spreadGetResponse = await fetch(FIREBASE_URL + "/counter/spread_" + spreadType + ".json");
        const currentSpreadCount = await spreadGetResponse.json() || 0;
        const newSpreadCount = currentSpreadCount + 1;
        
        await fetch(FIREBASE_URL + "/counter/spread_" + spreadType + ".json", {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(newSpreadCount)
        });
        
        updateSpreadCounterDisplay(spreadType, newSpreadCount);
        
      } catch (error) {
        console.error("Error incrementing counter:", error);
      }
    }
    
    function updateCounterDisplay(count) {
      const counter = document.getElementById('readingCounter');
      counter.textContent = count.toLocaleString();
      counter.classList.remove('counter-animate');
      void counter.offsetWidth;
      counter.classList.add('counter-animate');
    }
    
    document.addEventListener('DOMContentLoaded', () => {
      loadCounter();
      loadSpreadCounters();
    });
    
