    let question = '';
    let selectedCards = [];
    let shuffledCards = [];
    let spreadType = 3;
    let revealWrappers = [];
    let currentReadingId = null;
    
    // Month labels for 12-card spread
    const monthLabels = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
    
    function shuffleArray(array) {
      const arr = [...array];
      for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
      }
      return arr;
    }
    
    function selectSpread(num) {
      spreadType = num;
      document.querySelectorAll('.spread-option').forEach(el => el.classList.remove('selected'));
      event.currentTarget.classList.add('selected');
      
      setTimeout(() => {
        document.getElementById('step1').classList.remove('active');
        document.getElementById('step2').classList.add('active');
      }, 300);
    }
    
    function goBackToStep1() {
      document.getElementById('step2').classList.remove('active');
      document.getElementById('step1').classList.add('active');
      document.querySelectorAll('.spread-option').forEach(el => el.classList.remove('selected'));
    }
    
    function goBackToStep2() {
      document.getElementById('step3').classList.remove('active');
      document.getElementById('step2').classList.add('active');
      selectedCards = [];
    }
    
    function goToStep3() {
      const input = document.getElementById('questionInput');
      question = input.value.trim();
      
      document.getElementById('step2').classList.remove('active');
      document.getElementById('step3').classList.add('active');
      
      const questionDisplay = document.getElementById('questionDisplay');
      if (question) {
        questionDisplay.textContent = '"' + question + '"';
        questionDisplay.style.display = 'block';
      } else {
        questionDisplay.style.display = 'none';
      }
      
      document.getElementById('selectedCount').textContent = '0 / ' + spreadType;
      
      const preview = document.getElementById('selectedPreview');
      preview.innerHTML = '';
      for (let i = 1; i <= spreadType; i++) {
        const slot = document.createElement('div');
        slot.className = 'selected-slot';
        slot.id = 'slot' + i;
        slot.textContent = i;
        preview.appendChild(slot);
      }
      
      shuffledCards = shuffleArray(tarotCards);
      selectedCards = [];
      renderCards();
    }
    
    function renderCards() {
      renderArcSpread();
      renderMobileGrid();
    }
    
    function renderArcSpread() {
      const spread = document.getElementById('cardSpread');
      spread.innerHTML = '';
      
      const spreadWidth = spread.offsetWidth || 900;
      const spreadHeight = spread.offsetHeight || 400;
      const cardWidth = Math.min(95, spreadWidth * 0.1);
      
      const totalCards = shuffledCards.length;
      const arcRadius = spreadHeight * 0.95;
      const arcCenterX = spreadWidth / 2;
      const arcCenterY = spreadHeight + arcRadius * 0.25;
      const startAngle = -65;
      const endAngle = 65;
      const angleStep = (endAngle - startAngle) / (totalCards - 1);
      
      shuffledCards.forEach((card, index) => {
        const div = document.createElement('div');
        div.className = 'card-back';
        div.dataset.cardId = card.card_id;
        
        const angle = startAngle + (index * angleStep);
        const radians = angle * (Math.PI / 180);
        const x = arcCenterX + arcRadius * Math.sin(radians) - cardWidth / 2;
        const y = arcCenterY - arcRadius * Math.cos(radians);
        
        div.style.left = x + 'px';
        div.style.top = y + 'px';
        div.style.setProperty('--rotation', angle + 'deg');
        div.style.zIndex = index;
        
        div.onclick = () => toggleCard(card, div);
        spread.appendChild(div);
      });
    }
    
    function renderMobileGrid() {
      const grid = document.getElementById('gridContainer');
      grid.innerHTML = '';
      
      shuffledCards.forEach((card) => {
        const div = document.createElement('div');
        div.className = 'card-back';
        div.dataset.cardId = card.card_id;
        div.onclick = () => toggleCard(card, div);
        grid.appendChild(div);
      });
    }
    
    function toggleCard(card, element) {
      const existingIndex = selectedCards.findIndex(c => c.card_id === card.card_id);
      
      if (existingIndex !== -1) {
        selectedCards.splice(existingIndex, 1);
        document.querySelectorAll(`[data-card-id="${card.card_id}"]`).forEach(el => {
          el.classList.remove('selected');
        });
      } else {
        if (selectedCards.length >= spreadType) return;
        selectedCards.push(card);
        document.querySelectorAll(`[data-card-id="${card.card_id}"]`).forEach(el => {
          el.classList.add('selected');
        });
      }
      
      updateSelectionUI();
    }
    
    function updateSelectionUI() {
      document.getElementById('selectedCount').textContent = selectedCards.length + ' / ' + spreadType;
      
      for (let i = 1; i <= spreadType; i++) {
        const slot = document.getElementById('slot' + i);
        if (slot) {
          if (selectedCards.length >= i) {
            slot.classList.add('filled');
            slot.textContent = '';
          } else {
            slot.classList.remove('filled');
            slot.textContent = i;
          }
        }
      }
      
      if (selectedCards.length === spreadType) {
        setTimeout(() => goToStep4(), 600);
      }
    }
    
    function createCardWrapper(card, label, selectionOrder) {
      const wrapper = document.createElement('div');
      wrapper.className = 'result-card-wrapper' + (card.isReversed ? ' reversed' : '');
      wrapper.dataset.selectionOrder = selectionOrder;

      const cardName = card.isReversed ? `${card.card_name} ↓` : card.card_name;
      const imgClass = card.isReversed ? ' class="card-reversed"' : '';

      wrapper.innerHTML = `
        ${label ? '<p class="position-label">' + label + '</p>' : ''}
        <div class="result-card">
          <img src="${card.image}" alt="${card.card_name}"${imgClass}>
        </div>
        <h3 class="card-name">${cardName}</h3>
      `;
      revealWrappers.push({ wrapper, order: selectionOrder });
      return wrapper;
    }
    
    function revealCardsInOrder() {
      revealWrappers.sort((a, b) => a.order - b.order);
      revealWrappers.forEach((item, index) => {
        setTimeout(() => {
          item.wrapper.classList.add('revealed');
        }, 300 + index * 400);
      });
    }
    
    function goToStep4() {
      if (selectedCards.length !== spreadType) return;

      // Apply reversed status to cards if enabled
      if (typeof applyReversedStatus === 'function') {
        selectedCards = applyReversedStatus(selectedCards);
      }

      incrementReadingCount();

      document.getElementById('step3').classList.remove('active');
      document.getElementById('step4').classList.add('active');

      const resultQuestion = document.getElementById('questionDisplayResult');
      if (question) {
        resultQuestion.textContent = '"' + question + '"';
        resultQuestion.style.display = 'block';
      } else {
        resultQuestion.textContent = '';
        resultQuestion.style.display = 'none';
      }

      const container = document.getElementById('resultCards');
      container.innerHTML = '';
      container.className = 'result-cards layout-' + spreadType;

      revealWrappers = [];

      if (spreadType === 1) renderLayout1(container);
      else if (spreadType === 2) renderLayout2(container);
      else if (spreadType === 3) renderLayout3(container);
      else if (spreadType === 4) renderLayout4(container);
      else if (spreadType === 10) renderLayout10(container);
      else if (spreadType === 12) renderLayout12(container);

      // Save to history
      if (typeof saveReadingToHistory === 'function') {
        currentReadingId = saveReadingToHistory({
          question: question,
          spreadType: spreadType,
          cards: selectedCards,
          aiPrediction: null
        });
      }

      revealCardsInOrder();
    }
    
    function renderLayout1(container) {
      container.appendChild(createCardWrapper(selectedCards[0], '', 0));
    }
    
    function renderLayout2(container) {
      container.appendChild(createCardWrapper(selectedCards[0], '', 0));
      container.appendChild(createCardWrapper(selectedCards[1], '', 1));
    }
    
    function renderLayout3(container) {
      const labels = ['อดีต', 'ปัจจุบัน', 'อนาคต'];
      container.appendChild(createCardWrapper(selectedCards[0], labels[0], 0));
      container.appendChild(createCardWrapper(selectedCards[1], labels[1], 1));
      container.appendChild(createCardWrapper(selectedCards[2], labels[2], 2));
    }
    
    function renderLayout4(container) {
      const topRow = document.createElement('div');
      topRow.className = 'pyramid-top';
      topRow.appendChild(createCardWrapper(selectedCards[3], 'สรุป', 3));
      
      const bottomRow = document.createElement('div');
      bottomRow.className = 'pyramid-bottom';
      bottomRow.appendChild(createCardWrapper(selectedCards[0], 'อดีต', 0));
      bottomRow.appendChild(createCardWrapper(selectedCards[1], 'ปัจจุบัน', 1));
      bottomRow.appendChild(createCardWrapper(selectedCards[2], 'อนาคต', 2));
      
      container.appendChild(topRow);
      container.appendChild(bottomRow);
    }
    
    function renderLayout10(container) {
      const row1 = document.createElement('div');
      row1.className = 'row';
      row1.innerHTML = '<div class="row-label">อนาคต</div>';
      [5, 2, 9, 8].forEach((idx) => {
        row1.appendChild(createCardWrapper(selectedCards[idx], '', idx));
      });
      
      const row2 = document.createElement('div');
      row2.className = 'row';
      row2.innerHTML = '<div class="row-label">ปัจจุบัน</div>';
      [1, 0, 4, 7].forEach((idx) => {
        row2.appendChild(createCardWrapper(selectedCards[idx], '', idx));
      });
      
      const row3 = document.createElement('div');
      row3.className = 'row';
      row3.innerHTML = '<div class="row-label">อดีต</div>';
      
      const empty1 = document.createElement('div');
      empty1.className = 'empty-slot';
      row3.appendChild(empty1);
      
      row3.appendChild(createCardWrapper(selectedCards[3], '', 3));
      
      const empty2 = document.createElement('div');
      empty2.className = 'empty-slot';
      row3.appendChild(empty2);
      
      row3.appendChild(createCardWrapper(selectedCards[6], '', 6));
      
      container.appendChild(row1);
      container.appendChild(row2);
      container.appendChild(row3);
    }
    
    function renderLayout12(container) {
      // 12 cards for 12 months - grid layout 4x3
      // Cards in position order (ม.ค. to ธ.ค.)
      // But reveal in selection order
      for (let i = 0; i < 12; i++) {
        container.appendChild(createCardWrapper(selectedCards[i], monthLabels[i], i));
      }
    }
    
    function saveImage() {
      const container = document.getElementById('resultContainer');
      
      html2canvas(container, {
        backgroundColor: '#F7F4F0',
        scale: 2,
        useCORS: true,
        allowTaint: true,
        logging: false
      }).then(canvas => {
        const link = document.createElement('a');
        link.download = 'tarot-reading-' + Date.now() + '.png';
        link.href = canvas.toDataURL('image/png');
        link.click();
      }).catch(err => {
        alert('เกิดข้อผิดพลาดในการบันทึกรูป กรุณาลองใหม่อีกครั้ง');
        console.error(err);
      });
    }
    
    function restart() {
      question = '';
      selectedCards = [];
      shuffledCards = [];
      spreadType = 3;
      revealWrappers = [];
      
      document.getElementById('questionInput').value = '';
      document.querySelectorAll('.spread-option').forEach(el => el.classList.remove('selected'));
      
      document.getElementById('step4').classList.remove('active');
      document.getElementById('step1').classList.add('active');
    }
    
    let resizeTimeout;
    window.addEventListener('resize', () => {
      clearTimeout(resizeTimeout);
      resizeTimeout = setTimeout(() => {
        if (document.getElementById('step3').classList.contains('active')) {
          renderCards();
          selectedCards.forEach(card => {
            document.querySelectorAll(`[data-card-id="${card.card_id}"]`).forEach(el => {
              el.classList.add('selected');
            });
          });
        }
      }, 200);
    });
